function Announcement(){return <div className="announcement" data-testid="announcement-bar"><span className="pulse"/> 99%+ VERIFIED PURITY <i>•</i> HPLC + MASS SPEC TESTED <i>•</i> COA PER BATCH</div>}
function Navbar({onSearch,onCart,cartCount}){const [mobile,setMobile]=useState(false);return <><nav className="nav" data-testid="main-navigation"><Logo/><div className="navlinks">{[['/','Home'],['/products','Products'],['/collections','Goals'],['/guide','Peptide Guide'],['/about','About'],['/contact','Contact']].map(([to,label])=><Link className={to==='/'?'active':''} data-testid={`nav-${label.toLowerCase().replaceAll(' ','-')}`} to={to} key={to}>{label}</Link>)}</div><div className="navtools"><button data-testid="search-open-button" onClick={onSearch} aria-label="Search"><Search size={17}/><span>Search</span></button><Link to="/wishlist" data-testid="wishlist-nav-link"><Heart size={17}/></Link><Link to="/account" data-testid="account-nav-link"><UserRound size={17}/><span>Sign In</span></Link><button onClick={onCart} data-testid="cart-open-button" aria-label="Open cart"><ShoppingBag size={17}/><em data-testid="cart-count">{cartCount}</em></button></div><div className="mobiletools"><button data-testid="mobile-search-button" onClick={onSearch}><Search size={18}/></button><button data-testid="mobile-cart-button" onClick={onCart}><ShoppingBag size={18}/><em>{cartCount}</em></button><button data-testid="mobile-menu-button" onClick={()=>setMobile(!mobile)}><Menu size={20}/></button></div></nav>{mobile&&<div className="mobilemenu" data-testid="mobile-menu">{[['/','Home'],['/products','Products'],['/collections','Shop by Goal'],['/guide','Peptide Guide'],['/blog','Blog'],['/about','About'],['/quality','Quality'],['/shipping','Shipping'],['/contact','Contact'],['/wishlist','Wishlist'],['/account','Account']].map(([to,l])=><Link data-testid={`mobile-nav-${l.toLowerCase().replaceAll(' ','-')}`} onClick={()=>setMobile(false)} to={to} key={to}>{l}<ArrowRight size={16}/></Link>)}</div>}</>}
function SearchOverlay({open,onClose}){const [q,setQ]=useState('');const found=products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())).slice(0,7);if(!open)return null;return <div className="overlay" data-testid="search-overlay"><div className="searchbox"><button className="close" onClick={onClose} data-testid="search-close-button"><X/></button><label>SEARCH THE CATALOGUE</label><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products..." data-testid="search-input"/>{q&&<div className="searchresults">{found.map(p=><Link to={`/products/${p.slug}`} onClick={onClose} data-testid={`search-result-${p.slug}`} key={p.slug}><img src={p.image}/><span><b>{p.name}</b><small>{p.category}</small></span><strong>{money(p.price)}</strong></Link>)}</div>}</div></div>}
function AgeGate(){const [show,setShow]=useState(()=>localStorage.getItem('biotech-age')!=='yes');if(!show)return null;return <div className="overlay age" data-testid="age-verification-modal"><div className="agecard"><div className="monogram">BL</div><p className="eyebrow">PROFESSIONAL ACCESS</p><h2>ARE YOU 21 OR OLDER?</h2><p>BIOTECH LIFESCIENCES supplies HPLC-verified research compounds for qualified researchers and laboratory professionals.</p><div className="age-actions"><button className="primary" onClick={()=>{localStorage.setItem('biotech-age','yes');setShow(false)}} data-testid="age-yes-button">YES, I AM 21 OR OLDER — ENTER</button><button className="ghost" data-testid="age-no-button">NO, EXIT</button></div><small>By entering you acknowledge our terms of use.</small></div></div>}
function ProductCard({p,add,wishlist,setWishlist}){const [variant,setVariant]=useState(p.variants[0]);const liked=wishlist.includes(p.slug);return <article className="productcard" data-testid={`product-card-${p.slug}`}><div className="productimage"><span className="save">Save {p.discount}%</span><button className={liked?'heart liked':'heart'} onClick={()=>setWishlist(liked?wishlist.filter(x=>x!==p.slug):[...wishlist,p.slug])} data-testid={`wishlist-${p.slug}`} aria-label="Toggle wishlist"><Heart size={17} fill={liked?'currentColor':'none'}/></button><Link to={`/products/${p.slug}`} data-testid={`product-image-link-${p.slug}`}><img src={p.image} alt={p.name}/></Link></div><div className="productbody"><Link to={`/products/${p.slug}`} className="productname" data-testid={`product-name-${p.slug}`}>{p.name}</Link>{p.uses.length>0&&<div className="usetags" data-testid={`uses-${p.slug}`}>{p.uses.map(([label])=><span key={label}>{label}</span>)}</div>}<span className="selectlabel">SELECT SIZE</span><div className="variants">{p.variants.map(v=><button className={variant===v?'selected':''} onClick={()=>setVariant(v)} data-testid={`variant-${p.slug}-${v.replaceAll(' ','-')}`} key={v}>{v}</button>)}</div><div className="price"><strong>{money(p.price)}</strong><s>{money(p.compareAtPrice)}</s></div><div className="cardactions"><button className="ghost" onClick={()=>add(p,variant,false)} data-testid={`add-to-cart-${p.slug}`}>ADD TO CART</button><button className="primary" onClick={()=>add(p,variant,true)} data-testid={`buy-now-${p.slug}`}>BUY NOW</button></div></div></article>}
function CartDrawer({items,onClose,onUpdate,onCheckout}){return <div className="overlay draweroverlay" data-testid="cart-drawer"><aside className="drawer"><div className="drawerhead"><div><span className="eyebrow">ORDER MODULE</span><h2>YOUR CART <sup data-testid="drawer-count">{items.reduce((a,x)=>a+x.qty,0)}</sup></h2></div><button onClick={onClose} data-testid="cart-close-button"><X/></button></div>{items.length===0?<div className="empty"><ShoppingBag size={30}/><p>Your cart is currently empty.</p><Link to="/products" onClick={onClose} className="primary" data-testid="drawer-shop-button">BROWSE CATALOGUE</Link></div>:<><div className="cartitems">{items.map(x=><div className="cartitem" data-testid={`cart-item-${x.slug}`} key={x.slug+x.variant}><img src={x.image} alt={x.name}/><div><b>{x.name}</b><small>{x.variant}</small><div className="qty"><button onClick={()=>onUpdate(x,-1)} data-testid={`cart-minus-${x.slug}`}><Minus size={13}/></button><span data-testid={`cart-quantity-${x.slug}`}>{x.qty}</span><button onClick={()=>onUpdate(x,1)} data-testid={`cart-plus-${x.slug}`}><Plus size={13}/></button></div></div><strong>{money(x.price*x.qty)}</strong></div>)}</div><div className="drawersummary"><span>SUBTOTAL</span><strong data-testid="cart-subtotal">{money(items.reduce((a,x)=>a+x.price*x.qty,0))}</strong></div><button className="primary wide" onClick={onCheckout} data-testid="proceed-checkout-button">PROCEED TO CHECKOUT <ArrowRight size={16}/></button><button className="textbutton" onClick={onClose} data-testid="continue-shopping-button">CONTINUE SHOPPING</button></>}</aside></div>}
function Footer(){return <footer><div><Logo/><p>Research materials. Transparent documentation. Responsible supply.</p></div><div><b>SHOP</b><Link to="/products">Products</Link><Link to="/collections">Collections</Link><Link to="/wishlist">Wishlist</Link></div><div><b>COMPANY</b><Link to="/about">About</Link><Link to="/quality">Quality</Link><Link to="/blog">Blog</Link><Link to="/contact">Contact</Link></div><div><b>SUPPORT</b><Link to="/account">Account</Link><Link to="/shipping">Shipping</Link><Link to="/contact">Contact</Link></div><div><b>LEGAL</b><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link><Link to="/research-use-policy">Research Use</Link></div><small>© 2026 BIOTECH LIFESCIENCES · RESEARCH USE ONLY</small></footer>}
function Layout({children,cart,onCart}){const [search,setSearch]=useState(false);const [drawer,setDrawer]=useState(false);const nav=useNavigate();const add=(p,v,buy)=>{onCart(p,v);setDrawer(true);if(buy)nav('/checkout')};return <><div className="grain" aria-hidden="true"/><Announcement/><Navbar onSearch={()=>setSearch(true)} onCart={()=>setDrawer(true)} cartCount={cart.reduce((a,x)=>a+x.qty,0)}/><SearchOverlay open={search} onClose={()=>setSearch(false)}/>{children({add})}<Footer/>{drawer&&<CartDrawer items={cart} onClose={()=>setDrawer(false)} onUpdate={(x,d)=>onCart(x,x.variant,d)} onCheckout={()=>nav('/checkout')}/>}<AgeGate/></>}
function TrustBar(){return <div className="trustbar" data-testid="trust-bar">{[["High Purity","≥99% (HPLC)",ShieldCheck],["Lab Tested","Every Batch",FlaskConical],["Research Grade","Traceable",Beaker],["Research Use Only","Not for Human Use",FileText],["Fast Shipping","48h Dispatch",Truck]].map(([a,b,I])=><div key={a}><I size={17}/><b>{a}</b><small>{b}</small></div>)}</div>}
function ShopByGoal(){return <section className="goalsection" data-testid="goals-section"><div className="sectionhead"><div><span className="eyebrow">RIGHT PEPTIDE · RIGHT GOAL · REAL RESULTS</span><h2>Shop by goal</h2><p>Peptides curated by what they're actually studied for — pick your objective and see the compounds that fit.</p></div><Link to="/guide" data-testid="view-guide-link">FULL PEPTIDE GUIDE <ArrowRight size={16}/></Link></div><div className="goalgrid">{Object.entries(goalMap).map(([slug,{label,desc,icon:Icon}])=>{const count=products.filter(p=>p.goals.includes(slug)).length;return <Link className="goalcard" to={`/collections/${slug}`} data-testid={`goal-${slug}`} key={slug}><Icon size={26}/><h3>{label}</h3><p>{desc}</p><span className="goalcount">{count} COMPOUNDS <ArrowRight size={14}/></span></Link>})}</div></section>}
function Home({ctx}){return <><section className="hero"><div className="hero-copy"><div className="herobanner" data-testid="hero-banner-logo"><div className="herobanner-icon"><img src={LOGO_URL} alt="Biotech Life Sciences"/></div><div><span className="eyebrow">99%+ VERIFIED PURITY · HPLC + MS · COA PER BATCH</span></div></div><h1>BIOTECH<br/><span>LIFESCIENCES</span></h1><h2>Authentic compounds.<br/>Documented purity.</h2><p>Every batch is HPLC and Mass Spec tested with ≥99% verified purity. Certificate of Analysis available on request for every production lot — sourced from qualified manufacturers with a documented supply chain.</p><div className="actions"><Link className="primary" to="/products" data-testid="hero-browse-button">BROWSE THE CATALOGUE <ArrowRight size={16}/></Link><Link className="ghost" to="/guide" data-testid="hero-guide-button">PEPTIDE GUIDE</Link></div></div><ScientificVisual/></section><TrustBar/><section className="stats">{[['99%+','VERIFIED PURITY'],['25+','ACTIVE COMPOUNDS'],['HPLC · MS','BATCH TESTED'],['COA','PER BATCH']].map(([a,b],i)=><div data-testid={`hero-stat-${i}`} key={b}><FlaskConical size={16}/><strong>{a}</strong><span>{b}</span></div>)}</section><div className="ticker" data-testid="trust-ticker">99%+ VERIFIED PURITY <i>•</i> HPLC + MASS SPEC TESTED <i>•</i> COA PER BATCH <i>•</i> AUTHENTIC COMPOUNDS <i>•</i> DOCUMENTED SUPPLY CHAIN <i>•</i> PROFESSIONAL PACKAGING <i>•</i> PAN-INDIA SHIPPING <i>•</i> 48H DISPATCH</div><ShopByGoal/><ProductSection title="Handpicked Research Compounds" eyebrow="THE CATALOGUE" products={products.filter(p=>p.featured)} ctx={ctx}/><section className="features">{[['99%+ VERIFIED PURITY','HPLC-verified purity on every production batch. Documented, traceable, reproducible.',ShieldCheck],['HPLC + MASS SPEC','Analytical testing on every lot. Published purity and identity confirmation.',FlaskConical],['COA PER BATCH','Individual Certificate of Analysis per unit — request via email or WhatsApp.',FileText],['48H DISPATCH · PAN-INDIA','Cold-chain packaging where required. Nationwide shipping with tracking.',Truck]].map(([h,t,I])=><div className="feature" data-testid={`feature-${h.toLowerCase().replaceAll(' ','-').replaceAll('+','plus').replaceAll('·','')}`} key={h}><I/><h3>{h}</h3><p>{t}</p></div>)}</section><section className="protocol"><div><span className="eyebrow">THE BIOTECH STANDARD</span><h2>Purity you can<br/><span>verify.</span></h2></div><p>Every batch is HPLC and Mass Spec tested. Every unit ships with an accessible Certificate of Analysis. Clear identity, purity and storage information on every product page — before you order.</p><Link className="ghost" to="/quality">READ OUR PROTOCOL <ArrowRight size={16}/></Link></section></>}
function ScientificVisual(){const ref=useRef(null);useEffect(()=>{const canvas=ref.current;if(!canvas)return;const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(55,1,0.1,1000);const resize=()=>{const p=canvas.parentElement;const w=p.clientWidth||1;const h=p.clientHeight||1;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()};window.addEventListener('resize',resize);resize();camera.position.z=8;const dna=new THREE.Group();scene.add(dna);const turns=4;const pairs=48;const radius=1.8;const height=9;const sphereGeo=new THREE.SphereGeometry(0.14,20,20);const rungGeo=new THREE.CylinderGeometry(0.028,0.028,radius*2,10);const white=new THREE.MeshBasicMaterial({color:0xffffff});const dim=new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.5});const strandMat=new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:.85});const rungMat=new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.28});const s1Pts=[];const s2Pts=[];for(let i=0;i<pairs;i++){const t=(i/(pairs-1))*Math.PI*2*turns;const y=(i/(pairs-1)-0.5)*height;const x1=Math.cos(t)*radius,z1=Math.sin(t)*radius;const x2=Math.cos(t+Math.PI)*radius,z2=Math.sin(t+Math.PI)*radius;s1Pts.push(new THREE.Vector3(x1,y,z1));s2Pts.push(new THREE.Vector3(x2,y,z2));const sph1=new THREE.Mesh(sphereGeo,i%3===0?white:dim);sph1.position.set(x1,y,z1);dna.add(sph1);const sph2=new THREE.Mesh(sphereGeo,i%3===0?white:dim);sph2.position.set(x2,y,z2);dna.add(sph2);if(i%2===0){const rung=new THREE.Mesh(rungGeo,rungMat);rung.position.set((x1+x2)/2,y,(z1+z2)/2);rung.lookAt(new THREE.Vector3(x2,y,z2));rung.rotateX(Math.PI/2);dna.add(rung)}}const s1Geo=new THREE.BufferGeometry().setFromPoints(s1Pts);const s2Geo=new THREE.BufferGeometry().setFromPoints(s2Pts);dna.add(new THREE.Line(s1Geo,strandMat));dna.add(new THREE.Line(s2Geo,strandMat));const particlesGeo=new THREE.BufferGeometry();const pCount=140;const pPos=new Float32Array(pCount*3);for(let i=0;i<pCount*3;i+=3){pPos[i]=(Math.random()-0.5)*14;pPos[i+1]=(Math.random()-0.5)*12;pPos[i+2]=(Math.random()-0.5)*8}particlesGeo.setAttribute('position',new THREE.BufferAttribute(pPos,3));const particles=new THREE.Points(particlesGeo,new THREE.PointsMaterial({color:0xffffff,size:0.03,transparent:true,opacity:.55}));scene.add(particles);dna.rotation.z=0.14;let raf;const clock=new THREE.Clock();const animate=()=>{raf=requestAnimationFrame(animate);const t=clock.getElapsedTime();dna.rotation.y=t*0.35;particles.rotation.y=-t*0.05;renderer.render(scene,camera)};animate();return()=>{cancelAnimationFrame(raf);window.removeEventListener('resize',resize);renderer.dispose();sphereGeo.dispose();rungGeo.dispose();s1Geo.dispose();s2Geo.dispose();particlesGeo.dispose();white.dispose();dim.dispose();strandMat.dispose();rungMat.dispose()}},[]);return <div className="scientific"><canvas ref={ref} className="webgl-canvas"/><small>DNA / DOUBLE HELIX · SYSTEM 07</small></div>}
function ProductSection({title,eyebrow,products:ps,ctx}){return <section className="productsection"><div className="sectionhead"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2><p>Explore selected research materials with clear specifications, variant information and available documentation.</p></div><Link to="/products" data-testid="view-all-products">VIEW ALL PRODUCTS <ArrowRight size={16}/></Link></div><div className="productgrid">{ps.map(p=><ProductCard key={p.slug} p={p} {...ctx}/>)}</div></section>}
function ProductsPage({ctx}){const [q,setQ]=useState('');const [cat,setCat]=useState('All');const [sort,setSort]=useState('Featured');const filtered=useMemo(()=>products.filter(p=>(cat==='All'||p.category===cat)&&p.name.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>sort==='Price: Low to High'?a.price-b.price:sort==='Price: High to Low'?b.price-a.price:sort==='Name'?a.name.localeCompare(b.name):0),[q,cat,sort]);return <><PageIntro eyebrow="HANDPICKED RESEARCH COMPOUNDS" title="Research Product Catalogue" copy="Explore peptides, protein research materials, small molecules, coenzymes, blends and laboratory materials."/><section className="catalogue"><div className="filters"><label><Search size={15}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search catalogue" data-testid="catalogue-search-input"/></label><select value={cat} onChange={e=>setCat(e.target.value)} data-testid="category-filter"><option>All</option>{['Peptides','Proteins','Small Molecules','Coenzymes','Blends','Laboratory Materials'].map(x=><option key={x}>{x}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)} data-testid="sort-filter"><option>Featured</option><option>Price: Low to High</option><option>Price: High to Low</option><option>Name</option></select></div><p className="resultcount" data-testid="catalogue-result-count">{filtered.length} ACTIVE LISTINGS</p><div className="productgrid">{filtered.map(p=><ProductCard key={p.slug} p={p} {...ctx}/>)}</div></section></>}
function PageIntro({eyebrow,title,copy}){return <section className="pageintro"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></section>}
function RequestCOAModal({p,variant,onClose}){const subject=encodeURIComponent(`COA request — ${p.name} (${variant})`);const body=encodeURIComponent(`Hello BIOTECH LIFESCIENCES team,\n\nPlease share the Certificate of Analysis for:\n\nProduct: ${p.name}\nVariant: ${variant}\nBatch / Lot #: (if known)\n\nName:\nAffiliation / Laboratory:\n\nThank you.`);const wa=encodeURIComponent(`Hi BIOTECH LIFESCIENCES, I'd like to request the Certificate of Analysis for ${p.name} (${variant}).`);return <div className="overlay coaoverlay" data-testid="coa-modal"><div className="coamodal"><button className="close" onClick={onClose} data-testid="coa-close-button"><X/></button><span className="eyebrow">CERTIFICATE OF ANALYSIS</span><h2>Request the COA<br/>for {p.name}</h2><p>Every batch ships with an individual Certificate of Analysis documenting identity, purity (HPLC) and mass confirmation. Request the current batch report and we'll share it directly.</p><div className="coavariant"><span>Selected variant</span><b>{variant}</b></div><div className="coabuttons"><a className="primary" href={`mailto:${siteConfig.email}?subject=${subject}&body=${body}`} data-testid="coa-email-button">REQUEST BY EMAIL <ArrowRight size={16}/></a><a className="ghost" href={`https://wa.me/${siteConfig.whatsapp}?text=${wa}`} target="_blank" rel="noreferrer" data-testid="coa-whatsapp-button">REQUEST ON WHATSAPP</a></div><small>We reply within one business day · {siteConfig.supportHours}</small></div></div>}
function ProductDetail({ctx}){const {slug}=useParams();const p=products.find(x=>x.slug===slug)||products[0];const [variant,setVariant]=useState(p.variants[0]);const [qty,setQty]=useState(1);const [coa,setCoa]=useState(false);const related=products.filter(x=>x.slug!==p.slug&&x.goals.some(g=>p.goals.includes(g))).slice(0,4);return <><section className="detail"><div className="detailimage"><img src={p.image} alt={p.name}/></div><div className="purchase"><span className="eyebrow">{p.category} · HPLC + MASS SPEC VERIFIED</span><h1>{p.name}</h1><p className="overview" data-testid="product-overview">{p.overview}</p><div className="price big"><strong>{money(p.price)}</strong><s>{money(p.compareAtPrice)}</s><span>Save {p.discount}%</span></div><label className="selectlabel">SELECT SIZE</label><div className="variants large">{p.variants.map(v=><button className={variant===v?'selected':''} onClick={()=>setVariant(v)} data-testid={`detail-variant-${v}`} key={v}>{v}</button>)}</div><div className="detailbuy"><div className="qty"><button onClick={()=>setQty(Math.max(1,qty-1))} data-testid="detail-qty-minus"><Minus/></button><span data-testid="detail-quantity">{qty}</span><button onClick={()=>setQty(qty+1)} data-testid="detail-qty-plus"><Plus/></button></div><button className="primary" onClick={()=>{for(let i=0;i<qty;i++)ctx.add(p,variant,false)}} data-testid="detail-add-button">ADD TO CART <ShoppingBag size={16}/></button></div><button className="coa-request" onClick={()=>setCoa(true)} data-testid="request-coa-button"><FileText size={15}/> REQUEST CERTIFICATE OF ANALYSIS <ArrowRight size={14}/></button><div className="trustrow"><div><ShieldCheck size={16}/><b>≥99% PURITY</b><small>HPLC-verified per lot</small></div><div><FlaskConical size={16}/><b>MASS SPEC</b><small>Identity confirmed</small></div><div><Truck size={16}/><b>48H DISPATCH</b><small>Pan-India shipping</small></div></div></div></section>{p.howItWorks&&<section className="deepdive" data-testid="deep-dive-section"><div className="sectionhead"><div><span className="eyebrow">COMPOUND DEEP-DIVE</span><h2>How {p.name} works</h2><p>{p.howItWorks}</p></div></div><div className="deepgrid"><div className="deepcard"><span>BEST FOR</span><b>{p.bestFor}</b></div><div className="deepcard"><span>TYPICAL RESEARCH DOSE</span><b>{p.dose}</b></div><div className="deepcard"><span>HALF-LIFE</span><b>{p.halfLife}</b></div><div className="deepcard"><span>STUDIED GOALS</span><b>{p.goals.map(g=>goalMap[g]?.label).filter(Boolean).join(' · ')||'—'}</b></div></div></section>}{p.uses.length>0&&<section className="usessection" data-testid="uses-section"><div className="sectionhead"><div><span className="eyebrow">TOP RESEARCH APPLICATIONS</span><h2>What {p.name} is studied for</h2><p>The three most-documented research directions for {p.name}, explained in plain language.</p></div></div><div className="usegrid">{p.uses.map(([title,desc,Icon],i)=><div className="usecard" data-testid={`use-card-${i}`} key={title}><span className="usenum">0{i+1}</span><Icon size={22}/><h3>{title}</h3><p>{desc}</p></div>)}</div></section>}<section className="technical"><span className="eyebrow">TECHNICAL RECORD</span><h2>Product specifications</h2><div className="techgrid">{[['Product class',p.category],['Available sizes',p.variants.join(' / ')],['Purity','≥99% (HPLC)'],['Identity','Confirmed by Mass Spec'],['Appearance','White to off-white lyophilized powder'],['Storage','2–8 °C, protected from light'],['Reconstitution','Bacteriostatic water (0.9% benzyl alcohol)'],['Documentation','Batch-specific COA available on request'],['Classification','For laboratory research use only']].map(([a,b])=><div key={a}><span>{a}</span><b>{b}</b></div>)}</div><h2>Research overview</h2><p>{p.name} is supplied as a lyophilized research compound for in-vitro and laboratory investigation. Every production lot at BIOTECH LIFESCIENCES is analytically tested for identity and purity before it enters our inventory. Purity is confirmed by reverse-phase HPLC and identity by mass spectrometry, with results documented on a per-batch Certificate of Analysis.</p><p>Handling notes and reconstitution guidance are provided as reference. Storage and dilution protocols should always follow the procedures defined by the receiving laboratory. If you require the current batch COA, use the request panel above and we will share it directly.</p></section>{related.length>0&&<ProductSection title="Related research compounds" eyebrow="RELATED BY GOAL" products={related} ctx={ctx}/>}{coa&&<RequestCOAModal p={p} variant={variant} onClose={()=>setCoa(false)}/>}</>}
function InfoPage({title,eyebrow,copy,sections=[]}){return <><PageIntro eyebrow={eyebrow} title={title} copy={copy}/><section className="infosection">{sections.map(([h,t],i)=><div className="infoitem" key={h}><span>0{i+1}</span><div><h2>{h}</h2><p>{t}</p></div></div>)}</section></>}
function Collections(){return <><PageIntro eyebrow="RIGHT PEPTIDE · RIGHT GOAL" title="Shop by goal" copy="Explore compounds organised by the research directions they're studied for."/><section className="collectiongrid">{Object.entries(goalMap).map(([slug,{label,desc,icon:Icon}],i)=>{const items=products.filter(p=>p.goals.includes(slug));return <Link to={`/collections/${slug}`} className="collection" data-testid={`collection-${slug}`} key={slug}><span>0{i+1}</span><Icon/><h2>{label}</h2><p>{desc}</p><p className="goalcount">{items.length} COMPOUNDS · VIEW COLLECTION</p><ArrowRight/></Link>})}</section></>}
function GoalDetail({ctx}){const {slug}=useParams();const g=goalMap[slug];const items=products.filter(p=>p.goals.includes(slug));if(!g)return <ProductsPage ctx={ctx}/>;const Icon=g.icon;return <><section className="goalhero" data-testid={`goal-hero-${slug}`}><span className="eyebrow">SHOP BY GOAL</span><div className="goalheroline"><Icon size={44}/><h1>{g.label}</h1></div><p className="goalherodesc">{g.desc}</p><span className="goalherocount">{items.length} RESEARCH COMPOUNDS</span></section><section className="productsection"><div className="productgrid">{items.map(p=><ProductCard key={p.slug} p={p} {...ctx}/>)}</div></section></>}
function Guide(){return <><PageIntro eyebrow="QUICK REFERENCE" title="Peptide Cheat Sheet" copy="A scannable reference for every compound we stock — what it's studied for, how it works, and typical research dosing."/><section className="guide" data-testid="peptide-guide"><div className="guidebar"><ShieldCheck size={16}/><span>All entries are laboratory reference material. Research use only — not medical advice.</span></div>{Object.entries(goalMap).map(([gslug,{label,icon:Icon}])=>{const items=products.filter(p=>p.goals.includes(gslug));if(!items.length)return null;return <div className="guideblock" data-testid={`guide-block-${gslug}`} key={gslug}><div className="guideblockhead"><Icon size={22}/><h2>{label}</h2><small>{items.length} compounds</small></div><div className="guidetable"><div className="guiderow guidehead"><span>Compound</span><span>Best for</span><span>Typical dose</span><span>Half-life</span><span></span></div>{items.map(p=><Link to={`/products/${p.slug}`} className="guiderow" data-testid={`guide-row-${p.slug}`} key={p.slug}><span><b>{p.name}</b><small>{p.overview}</small></span><span>{p.bestFor}</span><span>{p.dose}</span><span>{p.halfLife}</span><span className="guidearrow"><ArrowRight size={15}/></span></Link>)}</div></div>})}</section></>}
function Blog(){return <><PageIntro eyebrow="FIELD NOTES" title="Research Journal" copy="Practical notes on sourcing, testing, documentation and responsible research material supply — written for laboratory practitioners."/><section className="articles">{[['Reading a Certificate of Analysis','What to look for on a COA — retention time, purity percent, method of analysis, mass spec confirmation and release date. A short field guide.'],['HPLC vs mass spec: what each one actually tells you','Purity and identity are different questions. This note explains why we run both and how to interpret the two reports side by side.'],['Handling lyophilized peptides at 2–8 °C','Storage, reconstitution and short-term working solutions — a practical protocol for laboratories receiving small-quantity research compounds.']].map(([h,t],i)=><article key={h}><span>0{i+1} / FIELD NOTE</span><h2>{h}</h2><p>{t}</p><Link to={`/blog/article-${i+1}`} data-testid={`article-link-${i}`}>READ ARTICLE <ArrowRight size={15}/></Link></article>)}</section></>}
function Checkout({cart}){return <><PageIntro eyebrow="SECURE ORDER MODULE" title="Checkout" copy="A local demonstration checkout. Payment processing and account authentication are not connected."/><section className="checkout"><form onSubmit={e=>e.preventDefault()}><span className="eyebrow">01 / CONTACT INFORMATION</span><input placeholder="Full name" data-testid="checkout-name"/><input placeholder="Email address" type="email" data-testid="checkout-email"/><input placeholder="Phone number" data-testid="checkout-phone"/><span className="eyebrow">02 / SHIPPING INFORMATION</span><input placeholder="Address" data-testid="checkout-address"/><div className="twocol"><input placeholder="City" data-testid="checkout-city"/><input placeholder="Postal code" data-testid="checkout-postcode"/></div><label className="ack"><input type="checkbox" data-testid="research-use-checkbox"/> I acknowledge research-use-only purchasing.</label><button className="primary wide" data-testid="place-demo-order-button">PLACE DEMO ORDER <ArrowRight size={16}/></button></form><div className="ordersummary"><span className="eyebrow">ORDER SUMMARY</span>{cart.map(x=><div key={x.slug}><span>{x.name} × {x.qty}<small>{x.variant}</small></span><b>{money(x.price*x.qty)}</b></div>)}<hr/><strong>TOTAL <b data-testid="checkout-total">{money(cart.reduce((a,x)=>a+x.price*x.qty,0))}</b></strong><p className="mocked">DEMO CHECKOUT · PAYMENT NOT CONNECTED</p></div></section></>}
function Wishlist({ctx}){const ps=products.filter(p=>ctx.wishlist.includes(p.slug));return <><PageIntro eyebrow="SAVED MATERIALS" title="Wishlist" copy="Keep a working list of products for future review."/><section className="productsection">{ps.length?<div className="productgrid">{ps.map(p=><ProductCard key={p.slug} p={p} {...ctx}/>)}</div>:<div className="empty pageempty"><Heart/><p>Your saved materials will appear here.</p><Link className="primary" to="/products">EXPLORE PRODUCTS</Link></div>}</section></>}
function App(){const [cart,setCart]=useState(()=>JSON.parse(localStorage.getItem('biotech-cart')||'[]'));const [wishlist,setWishlist]=useState(()=>JSON.parse(localStorage.getItem('biotech-wishlist')||'[]'));useEffect(()=>localStorage.setItem('biotech-cart',JSON.stringify(cart)),[cart]);useEffect(()=>localStorage.setItem('biotech-wishlist',JSON.stringify(wishlist)),[wishlist]);const update=(p,v,delta=1)=>setCart(old=>{const key=p.slug+v;const found=old.find(x=>x.slug+x.variant===key);if(found&&delta!==1){return found.qty+delta<=0?old.filter(x=>x!==found):old.map(x=>x===found?{...x,qty:x.qty+delta}:x)}if(found)return old.map(x=>x===found?{...x,qty:x.qty+1}:x);return [...old,{...p,variant:v,qty:1}]});const ctx={cart,onCart:update,wishlist,setWishlist};return <BrowserRouter><Layout cart={cart} onCart={update}>{render=><Routes><Route path="/" element={<Home ctx={{...ctx,...render}}/>}/><Route path="/products" element={<ProductsPage ctx={{...ctx,...render}}/>}/><Route path="/products/:slug" element={<ProductDetail ctx={{...ctx,...render}}/>}/><Route path="/collections" element={<Collections/>}/><Route path="/collections/:slug" element={<GoalDetail ctx={{...ctx,...render}}/>}/><Route path="/guide" element={<Guide/>}/><Route path="/blog" element={<Blog/>}/><Route path="/blog/:slug" element={<InfoPage eyebrow="FIELD NOTE" title="Research Journal" copy="A documentation-first note from BIOTECH LIFESCIENCES." sections={[["Research-use context","This editorial content is provided for research and documentation context only. [INSERT VERIFIED INFORMATION]"],["Source record","Original BIOTECH LIFESCIENCES editorial content. No medical-use claims are made."]]}/>}/><Route path="/about" element={<InfoPage eyebrow="THE COMPANY" title="Purity you can verify." copy="BIOTECH LIFESCIENCES supplies HPLC-verified research compounds to laboratories and independent researchers across India. Every batch is analytically tested. Every unit ships with an accessible Certificate of Analysis." sections={[["Our purpose","We started BIOTECH LIFESCIENCES because sourcing high-purity research compounds in India was slow, opaque and inconsistent. We wanted a supplier that put the analytical record — the actual HPLC and mass spec data — on the same page as the price."],["Sourcing & authentication","Every compound we list is procured from qualified manufacturers with a documented history. Incoming lots are matched against the manufacturer's Certificate of Analysis and re-tested for identity and purity before they enter our inventory."],["Analytical testing","We rely on two core techniques for release testing — reverse-phase HPLC to confirm ≥99% chemical purity, and mass spectrometry to confirm the correct molecular identity. Each production lot has its own report."],["Documentation on request","Every unit is sold with a batch-specific Certificate of Analysis. Use the Request COA panel on any product page and we'll send the current batch report by email or WhatsApp within one business day."],["Handling & fulfilment","Compounds are stored in temperature-controlled inventory. Orders are dispatched within 48 business hours in professional laboratory packaging with tracking, pan-India."],["Support","Our team responds to product, documentation and dispatch queries Monday to Saturday, 10:00 to 19:00 IST — by email, phone or WhatsApp."]]}/>}/><Route path="/quality" element={<InfoPage eyebrow="QUALITY PROTOCOL" title="Every batch. Every unit. Documented." copy="Our quality process is built around three commitments: verify identity, verify purity, and publish the record — before a compound ships." sections={[["Batch traceability","Every unit carries a batch reference that links directly to a production lot, an incoming COA from the manufacturer, our internal analytical report and the storage record. Nothing enters the catalogue without a lot number."],["HPLC purity verification","Purity is confirmed by reverse-phase HPLC on every production lot. Our release specification is ≥99% chemical purity. Batches that fall short are rejected — they are never blended, relabelled or resold."],["Mass spec identity","Identity is confirmed by mass spectrometry against the theoretical molecular mass. This is a second independent check that the compound in the vial is what the label states."],["Certificate of Analysis","A batch-specific Certificate of Analysis is prepared for every lot, capturing method, results and release date. You can request the current batch report on any product page — we send it directly by email or WhatsApp."],["Storage & handling","Compounds are held in temperature-controlled inventory. Lyophilized peptides are stored at 2–8 °C protected from light. Cold-chain packaging is used where the compound requires it."],["Supplier controls","We work with a short list of qualified manufacturers and audit incoming documentation on every lot. Suppliers are only added after direct commercial reference and independent identity testing."]]}/>}/><Route path="/shipping" element={<InfoPage eyebrow="FULFILMENT" title="48-hour dispatch. Pan-India shipping." copy="Orders are prepared, packed and shipped within 48 business hours. Every parcel is trackable end-to-end." sections={[["Order process","Orders received before 15:00 IST on a business day are prepared the same day. Address and contact details are reviewed against the order record before dispatch."],["Dispatch commitment","Standard dispatch window is 48 business hours from order confirmation. Time-sensitive orders can be flagged at checkout and we will contact you if an earlier dispatch is possible."],["Packaging","Compounds ship in professional laboratory packaging — sealed vials in cushioned inner packaging, tamper-evident outer packaging. Cold-chain packaging with gel packs is used where the compound requires it."],["Tracking","A tracking reference is issued when the parcel is picked up. Metro deliveries typically arrive in 2–3 business days; other locations in 3–6 business days depending on courier route."],["Returns & replacements","If a parcel arrives damaged or with a broken seal, notify us within 48 hours of delivery with photos and we will arrange a replacement at no additional charge."],["Support","Any dispatch question, tracking follow-up or delivery concern — write to "+siteConfig.email+" or reach us on WhatsApp during business hours."]]}/>}/><Route path="/contact" element={<InfoPage eyebrow="CONNECT WITH THE TEAM" title="Contact BIOTECH LIFESCIENCES" copy="Questions about a product, a Certificate of Analysis, an order in progress or a bulk laboratory quote — we respond within one business day." sections={[["Email",siteConfig.email],["Phone",siteConfig.phone],["WhatsApp","+91 98765 43210 · same number for calls and messages"],["Business hours",siteConfig.supportHours],["Certificate of Analysis","Use the Request COA panel on any product page — we'll send the current batch report by email or WhatsApp."],["Bulk & institutional","Laboratories, universities and research organisations can request institutional invoicing and volume pricing at "+siteConfig.email]]}/>}/><Route path="/wishlist" element={<Wishlist ctx={{...ctx,...render}}/>}/><Route path="/account" element={<InfoPage eyebrow="ACCOUNT MODULE" title="Your research account." copy="Account authentication is not connected in this local demo." sections={[["Sign in","[AUTHENTICATION NOT CONNECTED]"],["Orders","Order history will appear here after account services are connected."],["Profile","Save verified contact and shipping details after authentication is connected."]]}/>}/><Route path="/cart" element={<Checkout cart={cart}/>}/><Route path="/checkout" element={<Checkout cart={cart}/>}/>{['privacy','terms','disclaimer','research-use-policy'].map(x=><Route key={x} path={`/${x}`} element={<InfoPage eyebrow="LEGAL / RESEARCH USE" title={x.replaceAll('-',' ')} copy="[INSERT VERIFIED LEGAL INFORMATION]" sections={[["Research-use statement","Materials are intended for laboratory and in-vitro research only. Not for human consumption."],["Verified policy","Company-specific legal text will be published once supplied."]]}/>}/>)}</Routes>}</Layout><Routes/></BrowserRouter>}
export default App;